function starRecords(s){if(!hasOrbitChart(s))return [];return (s.primaries||[s.name]).map((name,i)=>({name,type:'Star',blackHole:s.centralBodyType==='black-hole'&&i===0,tag:s.centralBodyType==='black-hole'?(i?'Blue-white stellar companion':'Black hole'):s.primaries.length===3?(i===2?'Outer stellar companion':'Inner binary component'):s.primaries.length===2?'Binary component':'Central star',articleTitle:name,source:s.source,tint:s.starColors[i]||s.starColor,description:s.primaryDescriptions?.[i]??s.description,links:[systemArticleTitle(s),...s.primaries.filter(n=>n!==name)]}))}
